    q.resume();
    expect(q.isPaused()).toBe(false);
    expect(q.size()).toBe(4);
    expect(q.dequeue().payload).toBe("a");
    expect(q.dequeue().payload).toBe("b");
    expect(q.dequeue().payload).toBe("c");
    expect(q.dequeue().payload).toBe("d");
